import { execFileSync } from 'node:child_process';
import { mkdirSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { it } from 'vitest';
import { observeCodeStructure as observeNew } from './code-structure.js';
import { observeCodeStructure as observeOld } from './zz-code-structure-old.js';

// syzygy-bpyt.6.1, round 2 differential (not committed as a test). Part A injects each listing in the format each version asks for
// (old: no -z, new: -z). Part B runs both versions with their own default git runner over real fixture repositories, so the decoder
// in defaultRunGit is exercised. zz-code-structure-old.ts is the base module copied beside the new one.

const BASE = process.env['B61_BASE']!;
type Result = ReturnType<typeof observeNew>;
const outcome = (r: Result): string => r.kind === 'unknown' ? `Unknown (${r.reason})` : `Observed ${r.files.length}: ${JSON.stringify(r.files.map((f) => [f.path, f.sizeBytes, f.digest.slice(0, 18), f.language]))}`;

interface Case { readonly id: string; readonly plain: string; readonly z: string }
const id40 = 'a'.repeat(40);
const rec = (path: string, id = id40, size = '12', type = 'blob', mode = '100644'): string => `${mode} ${type} ${id} ${size.padStart(7)}\t${path}`;
const both = (id: string, records: readonly string[]): Case => ({ id, plain: records.join('\n') + '\n', z: records.join('\0') + '\0' });

const GIT_ENV = { ...process.env, GIT_CONFIG_GLOBAL: '/dev/null', GIT_CONFIG_SYSTEM: '/dev/null', GIT_AUTHOR_DATE: '2026-10-01T00:00:00Z', GIT_COMMITTER_DATE: '2026-10-01T00:00:00Z' };
const repo = (name: string): { root: string; g: (args: readonly string[], input?: Buffer) => string } => {
  const root = join(BASE, 'repos', name);
  rmSync(root, { recursive: true, force: true });
  mkdirSync(root, { recursive: true });
  const g = (args: readonly string[], input?: Buffer): string => execFileSync('git', ['-C', root, '-c', 'user.email=t@e.invalid', '-c', 'user.name=t', ...args], { env: GIT_ENV, ...(input === undefined ? {} : { input }) }).toString('utf8').trim();
  g(['init', '-q']);
  return { root, g };
};
/** A commit whose tree is built by `mktree -z` from raw entries, so path bytes need not be UTF-8. */
type Entry = readonly [Buffer, 'blob' | 'commit' | 'tree', string?];
const MODES = { blob: '100644', commit: '160000', tree: '040000' } as const;
const treeCommit = (name: string, entries: readonly Entry[], missing = false): { root: string; revision: string } => {
  const { root, g } = repo(name);
  const blob = g(['hash-object', '-w', '--stdin'], Buffer.from('x\n'));
  const mktree = (list: readonly Entry[]): string => g(['mktree', '-z', ...(missing ? ['--missing'] : [])],
    Buffer.concat(list.map(([path, type, id]) => Buffer.concat([Buffer.from(`${MODES[type]} ${type} ${id ?? blob}\t`), path, Buffer.from('\0')]))));
  // A `tree` entry without an id is a directory holding one blob, a.ts.
  const resolved = entries.map(([path, type, id]): Entry => (type === 'tree' && id === undefined ? [path, type, mktree([[Buffer.from('a.ts'), 'blob']])] : [path, type, id]));
  return { root, revision: g(['commit-tree', mktree(resolved), '-m', name]) };
};

it('round-2 differential', () => {
  rmSync(join(BASE, 'repos'), { recursive: true, force: true });

  // Part A: injected listings.
  const awkward = repo('awkward');
  const names = ['plain.ts', 'with space.md', 'tab\there.md', 'a "b".txt', 'ñ.md', 'line\nbreak.md', '"lead-quote.md', 'back\\slash.ts'];
  for (const name of names) { mkdirSync(dirname(join(awkward.root, name)), { recursive: true }); writeFileSync(join(awkward.root, name), 'x\n'); }
  awkward.g(['add', '-A']); awkward.g(['commit', '-qm', 'awkward']);
  const realPlain = execFileSync('git', ['-C', awkward.root, 'ls-tree', '-r', '-l', 'HEAD'], { encoding: 'utf8' });
  const realZ = execFileSync('git', ['-C', awkward.root, 'ls-tree', '-r', '-z', '-l', 'HEAD'], { encoding: 'utf8' });
  const plainLines = realPlain.split('\n').filter(Boolean), zRecords = realZ.split('\0').filter(Boolean);
  const cases: Case[] = [
    { id: 'real repo: all eight awkward names', plain: realPlain, z: realZ },
    ...zRecords.map((record, i) => ({ id: `real repo: only ${JSON.stringify(record.slice(record.indexOf('\t') + 1))}`, plain: plainLines[i]! + '\n', z: record + '\0' })),
    both('one plain blob', [rec('a.ts')]),
    both('submodule gitlink beside a blob', [rec('a.ts'), rec('vendor/sub', 'b'.repeat(40), '-', 'commit', '160000')]),
    both('blob without a size', [rec('a.ts', id40, '-')]),
    both('blob whose size git prints as BAD', [rec('a.ts', id40, 'BAD')]),
    both('SHA-256 object id', [rec('a.ts', 'c'.repeat(64))]),
    both('39-hex object id', [rec('a.ts', 'c'.repeat(39))]),
    both('garbage record after a blob', [rec('a.ts'), 'not a tree record']),
    both('mode corrupted', [rec('a.ts', id40, '12', 'blob', '10064x')]),
    both('type corrupted', [rec('a.ts', id40, '12', 'blbo')]),
    both('tab separator missing', [rec('a.ts').replace('\t', ' ')]),
    both('empty path', [rec('')]),
    both('size non-numeric', [rec('a.ts', id40, '1e3')]),
    both('uppercase hex id', [rec('a.ts', 'A'.repeat(40))]),
    both('symlink blob', [rec('link', id40, '4', 'blob', '120000')]),
    both('executable blob', [rec('run.sh', id40, '4', 'blob', '100755')]),
    { id: 'empty tree', plain: '', z: '' },
    { id: 'the -z request answered in the newline format', plain: rec('a.ts') + '\n', z: rec('a.ts') + '\n' },
    { id: 'the last -z record without its NUL', plain: [rec('a.ts'), rec('b.md')].join('\n') + '\n', z: `${rec('a.ts')}\0${rec('b.md')}` },
  ];
  const injected = (observe: typeof observeNew, listing: string, wantZ: boolean): Result => observe({
    repoRoot: '/unused', revision: 'r', capturedAt: 't',
    runGit: (_root, args) => { if (args.includes('-z') !== wantZ) throw new Error(`asked ${args.join(' ')}`); return listing; },
  });
  const partA = cases.map((c) => { const o = outcome(injected(observeOld, c.plain, false)); const n = outcome(injected(observeNew, c.z, true)); return { case: c.id, old: o, new: n, changed: o !== n }; });

  // Part B: real git, each version's own default runner.
  const emptyRepo = repo('empty');
  const emptyTree = emptyRepo.g(['mktree'], Buffer.from(''));
  const real: [string, { root: string; revision: string }][] = [
    ['awkward names (as Part A)', { root: awkward.root, revision: awkward.g(['rev-parse', 'HEAD']) }],
    ['two non-UTF-8 file names (0xf1.md, 0xf2.md)', treeCommit('non-utf8-files', [[Buffer.from([0xf1, 0x2e, 0x6d, 0x64]), 'blob'], [Buffer.from([0xf2, 0x2e, 0x6d, 0x64]), 'blob']])],
    ['two non-UTF-8 top-level directories (0xe8 te/, 0xe9 te/)', treeCommit('non-utf8-dirs', [[Buffer.from([0xe8, 0x74, 0x65]), 'tree'], [Buffer.from([0xe9, 0x74, 0x65]), 'tree']])],
    ['one non-UTF-8 name beside a UTF-8 one', treeCommit('non-utf8-one', [[Buffer.from('ok.ts'), 'blob'], [Buffer.from([0xff, 0x2e, 0x74, 0x73]), 'blob']])],
    ['a literal U+FFFD name (valid UTF-8)', treeCommit('literal-fffd', [[Buffer.from('�.md', 'utf8'), 'blob']])],
    ['a tree naming a missing blob', treeCommit('missing-blob', [[Buffer.from('present.ts'), 'blob'], [Buffer.from('missing.ts'), 'blob', 'd'.repeat(40)]], true)],
    ['a gitlink beside a blob', treeCommit('gitlink', [[Buffer.from('a.ts'), 'blob'], [Buffer.from('sub'), 'commit', 'b'.repeat(40)]], true)],
    ['the empty tree', { root: emptyRepo.root, revision: emptyRepo.g(['commit-tree', emptyTree, '-m', 'empty']) }],
  ];
  const partB = real.map(([id, { root, revision }]) => {
    const o = outcome(observeOld({ repoRoot: root, revision, capturedAt: 't' }));
    const n = outcome(observeNew({ repoRoot: root, revision, capturedAt: 't' }));
    return { case: id, old: o, new: n, changed: o !== n };
  });
  rmSync(join(BASE, 'repos'), { recursive: true, force: true });
  writeFileSync(process.env['B61_OUT']!, `${JSON.stringify({ partA, partB }, null, 1)}\n`);
});

import { createHash } from 'node:crypto';
import { cpSync, existsSync, writeFileSync } from 'node:fs';
import { it } from 'vitest';
import { observeCodeStructure } from '@syzygy/three-surface-poc-core';

import { renderOrreryPage } from './orrery.js';
import { renderPolarisPage } from './polaris.js';
import { renderPocPage } from './routes.js';
import { renderTrajectoryPage } from './trajectory.js';
import { buildFixtureModel, fixtureRepoWithGit } from './test-model-fixture.js';

// syzygy-bpyt.6.1, round 2 fixture byte identity (not committed as a test). The app's committed fixture repository is copied once to
// the fixed path B61_FIXED, so the repoRoot hashed into inputsDigest is equal across the two runs (new module, then the base module
// restored over it). Each surface is serialized and hashed separately; `all` hashes the JSON of every part.

it('fixture byte identity capture', () => {
  const cleanups: string[] = [];
  const fixed = process.env['B61_FIXED']!;
  const fresh = fixtureRepoWithGit(cleanups);
  if (!existsSync(fixed)) cpSync(fresh.repoRoot, fixed, { recursive: true });
  const repo = { repoRoot: fixed, revision: fresh.revision };
  const model = buildFixtureModel(cleanups, { fixtureRepo: repo });
  const parts: Record<string, string> = {
    model: JSON.stringify(model),
    orrery: renderOrreryPage(model),
    polaris: renderPolarisPage(model),
    trajectory: renderTrajectoryPage(model),
    poc: renderPocPage(model),
    codeStructure: JSON.stringify(observeCodeStructure({ repoRoot: fixed, revision: repo.revision, capturedAt: '2026-08-30T12:00:00Z' })),
  };
  const digests = Object.fromEntries(Object.entries(parts).map(([k, v]) => [k, { sha256: createHash('sha256').update(v).digest('hex'), bytes: Buffer.byteLength(v) }]));
  const all = createHash('sha256').update(JSON.stringify(parts)).digest('hex');
  const files = model.codeStructure.kind === 'observed' ? model.codeStructure.files.length : -1;
  writeFileSync(process.env['B61_OUT']!, `${JSON.stringify({ revision: repo.revision, files, all, digests }, null, 1)}\n`);
});
